SourceCode.Declaration:
/// <summary>
/// search result. ItemId / ItemName are set when the query is an item (number or barcode); Hits are the orders and journals found.
/// </summary>
[DataContractAttribute]
class HSMobileOpsSearchResponse
{
    boolean    success;
    str        errorCode;
    str        itemId;
    str        itemName;
    str        unitId;
    List       hits;
}

Method.Source:
[DataMemberAttribute('Success')]
public boolean parmSuccess(boolean _value = success)
{
    success = _value;
    return success;
}

[DataMemberAttribute('ErrorCode')]
public str parmErrorCode(str _value = errorCode)
{
    errorCode = _value;
    return errorCode;
}

[DataMemberAttribute('ItemId')]
public str parmItemId(str _value = itemId)
{
    itemId = _value;
    return itemId;
}

[DataMemberAttribute('ItemName')]
public str parmItemName(str _value = itemName)
{
    itemName = _value;
    return itemName;
}

[DataMemberAttribute('UnitId')]
public str parmUnitId(str _value = unitId)
{
    unitId = _value;
    return unitId;
}

[DataMemberAttribute('Hits'),
 DataCollectionAttribute(Types::Class, classStr(HSMobileOpsSearchHitRow))]
public List parmHits(List _value = hits)
{
    hits = _value;
    return hits;
}
